import com.medroute.dao.*; import com.medroute.model.*; import com.medroute.service.*; import com.zaxxer.hikari.HikariDataSource; import org.springframework.jdbc.core.JdbcTemplate; import java.lang.reflect.Field; import com.fasterxml.jackson.databind.ObjectMapper; public class TestAnalyze { public static void setField(Object obj, String fieldName, Object value) throws Exception { Field f = obj.getClass().getDeclaredField(fieldName); f.setAccessible(true); f.set(obj, value); } public static void main(String[] args) { HikariDataSource ds = new HikariDataSource(); ds.setDriverClassName("com.mysql.cj.jdbc.Driver"); ds.setJdbcUrl("jdbc:mysql://localhost:3306/medroute_ai?useSSL=false&serverTimezone=UTC"); ds.setUsername("root"); ds.setPassword("root"); JdbcTemplate jdbcTemplate = new JdbcTemplate(ds); DemandDAO demandDAO = new DemandDAO(jdbcTemplate); FacilityDAO facilityDAO = new FacilityDAO(); MedicineDAO medicineDAO = new MedicineDAO(); ObjectMapper mapper = new ObjectMapper(); AIDAO aiDAO = new AIDAO(jdbcTemplate, mapper); io.github.cdimascio.dotenv.Dotenv dotenv = io.github.cdimascio.dotenv.Dotenv.configure().ignoreIfMissing().load(); HuggingFaceClient hfClient = new HuggingFaceClient(dotenv, mapper); try { setField(facilityDAO, "jdbcTemplate", jdbcTemplate); setField(medicineDAO, "jdbcTemplate", jdbcTemplate); DemandService dService = new DemandService(demandDAO, facilityDAO, medicineDAO); AIService aiService = new AIService(aiDAO, hfClient, mapper, dotenv); DemandAnalysis a = dService.analyzeMedicine(999L, 999L); System.out.println("Calling aiService.getInsight(999L, 999L)..."); AIInsight insight = aiService.getInsight(999L, 999L, a, 999L); System.out.println("Insight Title: " + insight.getTitle()); } catch (Exception e) { e.printStackTrace(); } ds.close(); } }